<?php
namespace App\Modules\Sales\Presentation\Http\Controllers;
use App\Http\Controllers\Controller;use App\Modules\Sales\Application\CreateDraftSale;use App\Modules\Sales\Application\Data\CreateSaleData;use App\Modules\Sales\Application\Data\SaleLineData;use App\Modules\Sales\Application\Data\SalePaymentPlanData;use App\Modules\Sales\Presentation\Http\Requests\StoreSaleRequest;use Illuminate\Http\RedirectResponse;use Illuminate\Support\Carbon;
class StoreSaleController extends Controller {public function __invoke(StoreSaleRequest $request,CreateDraftSale $action):RedirectResponse{$d=$request->validated();$sale=$action->execute(new CreateSaleData($d['customer_profile_id']??null,$d['sales_order_id']??null,$d['price_list_id'],Carbon::parse($d['sold_at']),isset($d['due_at'])?Carbon::parse($d['due_at']):null,(int)$d['discount'],$request->user(),array_map(SaleLineData::fromArray(...),$d['lines']),array_map(SalePaymentPlanData::fromArray(...),$d['payments']??[])));return to_route('sales.show',$sale)->with('success','Borrador de venta creado. Revisa y confirma.');}}
